VALUES (currval('sequence_organizacion_id_organizacion'), 1, 'N', 36, 'La propuesta del movimiento es la rama "Manada" donde se propone promover el trabajo en quipo y los valores a traves de juegos, actividades en la naturaleza, actividades ludicas y de servios a la comunidad.', '7 a 11 años', 19.0, 'sabados de 15 a 18hs', NULL, 'F', NULL, 'Educadora Scout', 23.0, 'termino el roverismo (ultima rama que propone el movimiento) y decidio quedarse en el grupo siendo educadora');

