 -- -- -- INSERT DETALLE PROPUESTA NINIEZ JUVENTUD 
INSERT INTO detalle_propuesta_niniez_juventud (id_organizacion, id_propuesta, tipo_propuesta, id_detalle_propuesta, descripcion, edades, cant_participantes, dias_horarios, inicio_funcion, sexo_coordinador, otro_sexo, formacion, edad_coordinador, suma_org)
VALUES (currval('sequence_organizacion_id_organizacion'), 1, 'N', 40, 'Manada- Funcionan a traves del juego, teniendo como marco simbolico el libro de la selva, en este sentido, los educadores (adultos a cargo del grupo de niños/as) reciben el nombre de los personajes principales del cuento, cada uno con sus propias caracteristicas. A su vez los niños y niñas son llamados lobatos y lobeznas conformando diferentes Seisenas (grupos de niños y niñas). Asi como en el cuento los personajes en la selva atraviesan diversos obstaculos y etapas, el funcionamiento de la manada es el mismo, ya que se establecen etapas que el niño va superando a medida que va creciendo. Asi, se organizan las diversas actividades teniendo como eje central la educacion en valores a traves de la naturaleza.', '7a 11 años', 20.0, 'sabados  15 a 18hs', '1991-03-16', 'F', NULL, 'educador scout', 55.0, 'se sumo como mama ayudante y luego se formo como educadora scout');

INSERT INTO detalle_propuesta_niniez_juventud (id_organizacion, id_propuesta, tipo_propuesta, id_detalle_propuesta, descripcion, edades, cant_participantes, dias_horarios, inicio_funcion, sexo_coordinador, otro_sexo, formacion, edad_coordinador, suma_org)
VALUES (currval('sequence_organizacion_id_organizacion'), 1, 'N', 41, 'UNIDAD-  Propuesta de juego educativo con enfasis en trabajo en equipo, con trabajo en las habilidades de liderazgo y cooperacion, y la participacion de jovenes en el proceso de toma de decisiones y preferentemente el marco de actividades de juego y aventuras en la naturaleza.', '11 A 14 AÑOS', 20.0, 'sabados de 15 a 18hs', NULL, 'F', NULL, 'educadora scout', 26.0, 'desde niña luego de pasar su camino scout.');

INSERT INTO detalle_propuesta_niniez_juventud (id_organizacion, id_propuesta, tipo_propuesta, id_detalle_propuesta, descripcion, edades, cant_participantes, dias_horarios, inicio_funcion, sexo_coordinador, otro_sexo, formacion, edad_coordinador, suma_org)
VALUES (currval('sequence_organizacion_id_organizacion'), 2, 'J', 26, 'caminantes- la prpuesta para este grupo de edad se enfoca en las habilidades de participacion democratica y toma de decisiones, el aprendizaje a traves de proyectos y las actividades solidarias con otras instituciones de la comunidad barrial; lo cual complementa la oferta de actividades de aventura en la naturaleza.', '14 a 17 años', 12.0, 'sabados 15 a 18hs', NULL, 'M', NULL, 'educador scout', 28.0, 'desde chico en el grupo');

INSERT INTO detalle_propuesta_niniez_juventud (id_organizacion, id_propuesta, tipo_propuesta, id_detalle_propuesta, descripcion, edades, cant_participantes, dias_horarios, inicio_funcion, sexo_coordinador, otro_sexo, formacion, edad_coordinador, suma_org)
VALUES (currval('sequence_organizacion_id_organizacion'), 2, 'J', 27, 'rover-que comprende el ultimo tramo del recorrido del joven en el camino como "beneficiaro" o "protagonista", donde se encuentra en el proceso del comienzo de la vida adulta, tambien aqui se proponen etapas, lo que busca es la independencia del joven con menos participacion adulta, acompañando a que el joven pueda hacer su camino con su individualidad formada pero siempre trabajando en equipo. en esta rama no hay equipos, ni patrullas ni seisenas.', '17 a 21', 5.0, 'sabados de 15 a 18hs', NULL, 'F', NULL, 'educadora scout', 30.0, 'esta desde chica en el grupo');

