-- ==========================================
-- 9 - Insertar direcciones vacias
-- ==========================================
INSERT INTO direccion (id_organizacion, id_direccion, id_ciudad, calle)
SELECT 
    o.id_organizacion,
    nextval('sequence_direccion_id_direccion'::regclass), 
    1,
    ''
FROM organizacion o
WHERE NOT EXISTS (
    SELECT 1 
    FROM direccion d 
    WHERE d.id_organizacion = o.id_organizacion
);

